const typeNotes={FIRE:'A faint warmth follows its movements.',ICE:'The air feels cooler beside it.',ELECTRIC:'A tiny spark flickers and fades.',GRASS:'It seems especially interested in the nearby greenery.',GHOST:'Its presence feels strangely quiet.',PSYCHIC:'For a moment, it seems to anticipate your next thought.',WATER:'It notices even the smallest trace of moisture.',STEEL:'Its metallic details catch a little light.',ROCK:'It takes a particular interest in the stones nearby.',DRAGON:'There is a quiet confidence in the way it carries itself.',FAIRY:'The ordinary surroundings seem a little more magical beside it.',DARK:'It seems comfortable lingering at the edge of the shadows.',BUG:'It notices tiny details you might have missed.',FLYING:'It follows the changing currents of the breeze.',FIGHTING:'It seems to be paying attention to your stance.',GROUND:'It takes a steady interest in the terrain.',POISON:'You are careful to give it room when it moves.',NORMAL:'It seems to find something interesting in everyday things.'};
export function behaviourFor(index,mood,name,gesture,species){
 const action=COMPANION_ACTIONS[index%100].replaceAll('{name}',name).replaceAll('{gesture}',gesture);
 const ending=MOOD_ENDINGS[mood][index%10];
 return action+' '+ending+(index%7===0?' '+(typeNotes[species.types[0]]||''):'');
}
export const COMPANION_BEHAVIOUR_COUNT=COMPANION_ACTIONS.length*Object.keys(MOOD_ENDINGS).length;
